parameters.query:
SET LOCAL app.current_tenant = $json.tenantId;

INSERT INTO conversations (tenant_id, channel, contact_ref, status, escalado, created_at)
VALUES ($json.tenantId, 'whatsapp_text', $json.contactRef, 'abierta', false, to_timestamp($json.timestamp / 1000))
ON CONFLICT DO NOTHING
RETURNING id;

SET LOCAL app.current_tenant = $json.tenantId;

WITH conv AS (
  SELECT id FROM conversations
  WHERE tenant_id = $json.tenantId AND contact_ref = $json.contactRef AND channel = 'whatsapp_text'
  ORDER BY created_at DESC LIMIT 1
)
INSERT INTO messages (conversation_id, tenant_id, direction, content, ai_generated, tokens_used, created_at)
SELECT conv.id, $json.tenantId, 'in', $json.message, false, 0, to_timestamp($json.timestamp / 1000)
FROM conv
RETURNING id;

