parameters.query:
SET LOCAL app.current_tenant = $json.tenantId;

UPDATE conversations SET escalado = true, status = 'escalada'
WHERE tenant_id = $json.tenantId AND contact_ref = $json.contactRef AND channel = 'whatsapp_text';

INSERT INTO audit_log (tenant_id, actor_id, action, meta, created_at)
VALUES ($json.tenantId, $json.contactRef, 'conversation.escalated',
  jsonb_build_object('reason', 'keyword_or_ai', 'message', $json.message),
  NOW());
